import {randomBytes, scryptSync, createCipheriv, createDecipheriv} from 'node:crypto';
const MAGIC=Buffer.from('OMNIBLOB1');
const SALT_SIZE=16, NONCE_SIZE=12, TAG_SIZE=16;
export function isEncryptedBlob(buf){return buf.subarray(0,MAGIC.length).equals(MAGIC);}
function keyFor(passphrase,salt){if(typeof passphrase!=='string'||passphrase.length<16)throw Error('Encrypted attachments require a strong OMNI_MEMORY_PASSPHRASE.');return scryptSync(passphrase,salt,32,{N:16384,r:8,p:1,maxmem:64*1024*1024});}
export function encryptBlob(bytes,passphrase){const salt=randomBytes(SALT_SIZE),nonce=randomBytes(NONCE_SIZE),cipher=createCipheriv('aes-256-gcm',keyFor(passphrase,salt),nonce);cipher.setAAD(MAGIC);const ciphertext=Buffer.concat([cipher.update(bytes),cipher.final()]);return Buffer.concat([MAGIC,salt,nonce,cipher.getAuthTag(),ciphertext]);}
export function decryptBlob(bytes,passphrase){if(!isEncryptedBlob(bytes))throw Error('Not an encrypted OmniMemory attachment.');const base=MAGIC.length;if(bytes.length<base+SALT_SIZE+NONCE_SIZE+TAG_SIZE)throw Error('Truncated encrypted attachment.');const salt=bytes.subarray(base,base+SALT_SIZE),nonce=bytes.subarray(base+SALT_SIZE,base+SALT_SIZE+NONCE_SIZE),tag=bytes.subarray(base+SALT_SIZE+NONCE_SIZE,base+SALT_SIZE+NONCE_SIZE+TAG_SIZE);try{const decipher=createDecipheriv('aes-256-gcm',keyFor(passphrase,salt),nonce);decipher.setAAD(MAGIC);decipher.setAuthTag(tag);return Buffer.concat([decipher.update(bytes.subarray(base+SALT_SIZE+NONCE_SIZE+TAG_SIZE)),decipher.final()]);}catch{throw Error('Cannot decrypt attachment: incorrect passphrase or modified bytes.');}}
